            keywords_faculty_set.add(faculty.replace('学院', ''))  # 去除学院
        keywords_faculty_set.add(faculty.replace('学院', '专业'))  # 替换为专业
        keywords_faculty_set.add(faculty.replace('学院', '院'))  # 替换为院
        keywords_faculty_set.add(faculty.replace('学院', '系'))  # 替换为系
    if '系' in faculty:
        if len(faculty.replace('系', '')) >= 3:
            keywords_faculty_set.add(faculty.replace('系', ''))  # 去除系

# 去除重复的关键词并生成正则表达式模式
extract_pattern_faculty = re.compile('|'.join(re.escape(keyword) for keyword in keywords_faculty_set))

with open(os.path.abspath(os.path.dirname(__file__) + '/../data/rules/faculty.json'), 'r', encoding='utf-8') as f:
    faculty_abbreviation_map = json.load(f)
    faculty_abbreviation_pattern = re.compile('|'.join(re.escape(key) for key in faculty_abbreviation_map.keys()))

def extract_faculty_from_text(text):
    text = text.replace('系统', '的系统')
    matches = extract_pattern_faculty.findall(text)
    if matches:
        processed_matches = []
        for match in matches:
            if match.endswith('专业'):
                processed_match = match.replace('专业', '学院')
            elif match.endswith('院'):
                processed_match = match.replace('院', '学院')
            elif match.endswith('系'):
                processed_match = match.replace('系', '学院')
            else:
                processed_match = match
            processed_matches.append(processed_match)
        processed_matches = list(set(processed_matches))
        return ','.join(processed_matches)
    else:
        return extract_and_map_abbreviation(text, faculty_abbreviation_map, faculty_abbreviation_pattern)


